def max_vowels(s, k):
    vowels = set('aeiou')
    count = sum(1 for c in s[:k] if c in vowels)      # first window, counted once
    best = count
    for i in range(k, len(s)):
        if s[i] in vowels:
            count += 1                                  # entering character
        if s[i - k] in vowels:
            count -= 1                                  # leaving character
        best = max(best, count)
    return best

